/**
 * Seeded property tests for the signed-URL codec (`HmacUrlSigner`).
 *
 * Paths and params are generated by a small deterministic PRNG (mulberry32)
 * from URL metacharacters, percent signs, reserved-looking names, Unicode, and
 * prototype names. The properties: `verify(sign(x))` returns exactly `x`; any
 * single-character mutation, deletion, or insertion in the signed URL either
 * fails verification or verifies to the identical `{ path, params }` (an
 * alternative spelling of the same value), so no edit can change what the
 * signature vouches for; and `verify` never throws.
 */

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import { HmacUrlSigner } from '../../src/routing/signed-urls.js';

// ---------------------------------------------------------------------------
// Seeded generator
// ---------------------------------------------------------------------------

const BASE_SEED = 0x5197_6001;
const RUNS = 300;

/** mulberry32: a tiny, well-distributed 32-bit PRNG; same seed, same sequence. */
function mulberry32(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

interface Gen {
  int(min: number, max: number): number;
  pick<T>(items: readonly T[]): T;
  text(maxParts: number): string;
}

const PIECES = [
  'a',
  'Z',
  '0',
  '-',
  '_',
  '.',
  '~',
  ' ',
  '+',
  '%',
  '%20',
  '%zz',
  '&',
  '=',
  ';',
  ',',
  '/',
  ':',
  '@',
  '!',
  '$',
  "'",
  '(',
  '*',
  '[',
  ']',
  'é',
  '😀',
  ' ',
  '\u0000',
  '__proto__',
  'constructor',
  'signature',
  'expires',
];

function generator(seed: number): Gen {
  const next = mulberry32(seed);
  const gen: Gen = {
    int: (min, max) => min + Math.floor(next() * (max - min + 1)),
    pick: (items) => items[Math.floor(next() * items.length)]!,
    text: (maxParts) => {
      let out = '';
      for (let i = gen.int(0, maxParts); i > 0; i -= 1) out += gen.pick(PIECES);
      return out;
    },
  };
  return gen;
}

function forAll(check: (gen: Gen) => void): void {
  for (let run = 0; run < RUNS; run += 1) {
    const caseSeed = (BASE_SEED + run) >>> 0;
    try {
      check(generator(caseSeed));
    } catch (error) {
      assert.fail(`property failed for seed ${caseSeed}: ${(error as Error).message}`);
    }
  }
}

// ---------------------------------------------------------------------------
// Fixtures
// ---------------------------------------------------------------------------

const KEY = 'signed-url-property-key-0123456789abcdef';
const NOW = 1_700_000_000_000;
const signer = new HmacUrlSigner({ key: KEY, now: () => NOW });

const MUTATION_CHARACTERS = [
  'a',
  'A',
  '0',
  '%',
  '&',
  '=',
  '?',
  '#',
  '+',
  '/',
  '.',
  ' ',
  '\u0000',
  'é',
];

interface Signed {
  readonly path: string;
  readonly params: Record<string, string>;
  readonly url: string;
}

function signedCase(gen: Gen): Signed {
  const path = `/${gen.text(6).replace(/[?#]/g, '')}`;
  const params: Record<string, string> = {};
  for (let i = gen.int(0, 4); i > 0; i -= 1) {
    const name = gen.text(3);
    if (name === 'signature' || name === 'expires' || name === '') continue;
    Object.defineProperty(params, name, {
      value: gen.text(5),
      enumerable: true,
      writable: true,
      configurable: true,
    });
  }
  return { path, params, url: signer.sign(path, params, gen.pick([0, 60_000])) };
}

/** One random single-character edit: replace, delete, or insert. */
function mutate(gen: Gen, url: string): string {
  const index = gen.int(0, url.length - 1);
  const character = gen.pick(MUTATION_CHARACTERS);
  switch (gen.int(0, 2)) {
    case 0:
      return url.slice(0, index) + character + url.slice(index + 1);
    case 1:
      return url.slice(0, index) + url.slice(index + 1);
    default:
      return url.slice(0, index) + character + url.slice(index);
  }
}

// ---------------------------------------------------------------------------
// Properties
// ---------------------------------------------------------------------------

describe('property: HmacUrlSigner', () => {
  it('verify(sign(path, params)) returns exactly the signed path and params', () => {
    forAll((gen) => {
      const { path, params, url } = signedCase(gen);
      const verified = signer.verify(url);
      assert.ok(verified !== null, `round trip failed for ${JSON.stringify(url)}`);
      assert.equal(verified.path, path);
      assert.deepEqual({ ...verified.params }, { ...params });
    });
  });

  it('a single-character edit never changes what the signature vouches for', () => {
    forAll((gen) => {
      const { path, params, url } = signedCase(gen);
      for (let edit = 0; edit < 20; edit += 1) {
        const mutated = mutate(gen, url);
        if (mutated === url) continue;
        const verified = signer.verify(mutated);
        if (verified === null) continue;
        assert.equal(verified.path, path, `edit ${JSON.stringify(mutated)} changed the path`);
        assert.deepEqual(
          { ...verified.params },
          { ...params },
          `edit ${JSON.stringify(mutated)} changed a param`,
        );
      }
    });
  });

  it('never throws on arbitrary text', () => {
    forAll((gen) => {
      const input = `${gen.pick(['', '/', '?', '/x?'])}${gen.text(12)}`;
      const verified = signer.verify(input);
      assert.ok(verified === null || typeof verified.path === 'string');
    });
  });

  it('never verifies a URL signed under another key', () => {
    const other = new HmacUrlSigner({
      key: 'another-property-key-0123456789abcdefgh',
      now: () => NOW,
    });
    forAll((gen) => {
      const { path, params } = signedCase(gen);
      assert.equal(signer.verify(other.sign(path, params)), null);
    });
  });
});
